Object.assign(ACTS.stars,{l6:X('เฝ้ารอดาวโซพเดตขึ้นก่อนรุ่ง','Watch for Sopdet to rise before dawn'),c6:X('นั่งดูดาวบนหลังคาบ้าน','Watch the stars from the roof')});
