Object.assign(INV,{linen:{n:X('ผ้าลินิน','linen cloth'),v:2},dfish:{n:X('ปลาตากแห้ง','dried fish'),v:1}});
const hireNote6=X('ชาวอียิปต์เขียนจดหมายและบัญชีบนกระดาษปาปิรุส ซึ่งทำจากต้นกกปาปิรุสที่ฝานเป็นเส้นบาง วางซ้อนขวางกัน แล้วทุบให้ติดเป็นแผ่น ปาปิรุสมีราคาแพง ข้อความสั้นๆ ในชีวิตประจำวันจึงมักเขียนบนเศษหินปูนหรือเศษหม้อแทน คนที่อ่านไม่ออกจ้างอาลักษณ์เขียนให้','Egyptians wrote letters and accounts on papyrus, made from strips of the papyrus reed laid crosswise and beaten into a sheet. Papyrus was costly, so short everyday notes were often written on flakes of limestone or broken pottery instead. People who could not read hired a scribe.');
const canWrite6=S=>S.lit>=35||S.ag>=1;
const NOWRITE6=X('ต้องอ่านเขียนได้ หรือมีของมูลค่าหนึ่งเดเบนไว้จ้างอาลักษณ์','You must read and write, or have a deben’s worth of goods to hire a scribe');
function doWrite6(S,k){if(S.lit>=35){S.papN++;S.papK[k]=(S.papK[k]||0)+1;return 1}S.ag=Math.max(0,S.ag-1);return 0}
const wOpt6=(l,run)=>Object.assign(opt(l,run),{lockF:S=>!canWrite6(S),lockT:NOWRITE6});
const corvee6=(id,deck,a)=>({id,deck,w:4,ch:6,a,rep:6,cond:S=>S.cls!=='elite',t:X('ฤดูน้ำหลาก งานของพระราชา','The flood season: the king’s work'),
 xf:S=>{const pyr=era6(S.ya)==='ok'&&['mem','giz','del','aby'].includes(S.rg);return pyr?X('น้ำท่วมทุ่งนาจนมิด ทำนาไม่ได้อีกหลายเดือน เจ้าหน้าที่ของพระราชามาเรียกคนจากทุกหมู่บ้านไปลากหินสร้างพีระมิดที่กีซา','The fields lie under water and no one can farm for months. The king’s officials come to call people from every village to haul stone for the pyramid at Giza.'):X('น้ำท่วมทุ่งนาจนมิด ทำนาไม่ได้อีกหลายเดือน เจ้าหน้าที่มาเรียกคนจากทุกหมู่บ้านไปทำงานให้พระราชา ขุดคลองและสร้างวิหาร','The fields lie under water and no one can farm for months. Officials come to call people from every village to work for the king, digging canals and building temples.')},
 n:X('ในฤดูน้ำหลาก (อาเคต) ราวเดือนกรกฎาคมถึงตุลาคม ทุ่งนาจมน้ำ รัฐจึงเกณฑ์แรงงานไปทำงานก่อสร้าง ทีมคนงานที่กีซามีชื่อเรียกอย่าง “เพื่อนของคูฟู” และ “ขี้เมาของเมนคาวเร” ซึ่งเขียนไว้บนก้อนหิน กระดาษปาปิรุสจากราชอาณาจักรกลางแผ่นหนึ่งบันทึกรายชื่อคนที่หนีงานเกณฑ์ และครอบครัวที่ถูกกักตัวไว้จนกว่าเขาจะกลับมา','In the flood season (Akhet), roughly July to October, the fields were under water and the state called up labour for building. Work gangs at Giza had names like “Friends of Khufu” and “Drunkards of Menkaure”, written on the stones. A Middle Kingdom papyrus lists people who fled their labour duty, and family members held until they returned.'),
 o:[opt(X('ไปทำงานกับทีมของหมู่บ้าน','Go and work with your village gang'),S=>{fx({h:-3,b:4,f:3});if(rnd()<.15){S.inj=1;return X('หินก้อนหนึ่งลื่นทับเท้าคุณ เพื่อนในทีมหามคุณไปหาหมอ ซึ่งพันแผลด้วยผ้าลินินและน้ำผึ้ง','A block slips onto your foot. Your gang carries you to the physician, who binds it with linen and honey.')}return X('งานหนักจนมือพอง แต่ได้กินขนมปัง เบียร์ และบางวันมีเนื้อวัว ตอนกลับบ้าน คุณมีเพื่อนใหม่จากหลายหมู่บ้าน','The work blisters your hands, but there is bread, beer and some days even beef. You come home with friends from many villages.')}),
    Object.assign(opt(X('ส่งของขวัญให้เจ้าหน้าที่ ให้คนอื่นไปแทน','Send the official a gift so someone else goes'),S=>{S.ag-=2;fx({p:-1});return X('เจ้าหน้าที่รับของ แล้วขีดชื่อคุณออก มีคนอื่นต้องไปแทน','The official takes the gift and crosses out your name. Someone else goes in your place.')}),{lockF:S=>S.ag<2,lockT:X('ต้องมีของมูลค่า 2 เดเบน','Needs 2 deben in goods')}),
    opt(X('หนีไปซ่อนในบึงปาปิรุส','Run away to hide in the papyrus marshes'),S=>{if(rnd()<.5){fx({b:-8,p:-4});return X('คุณถูกตามจับได้ ระหว่างนั้นครอบครัวของคุณถูกกักตัวไว้แทน','You are tracked down; meanwhile your family has been held in your place.')}fx({b:-3,f:-4});return X('คุณซ่อนตัวกับยุงในบึงจนน้ำลด ไม่มีใครตามมาถึง','You hide with the mosquitoes in the marsh until the water falls. No one comes after you.')})]});

const DEC6=[
/* ----- childhood ----- */
{id:'c6_name',deck:'child',w:3,ch:6,a:[5,9],t:X('ความหมายของชื่อคุณ','What your name means'),
 xf:S=>X('แม่บอกว่าชื่อ '+S.nm6.th+' ของคุณแปลว่า '+S.nm6.mean.th+' และบอกว่าตราบใดที่ยังมีคนเอ่ยชื่อของเรา เราก็ยังมีชีวิตอยู่ แม้ตายไปแล้วก็ตาม','Your mother tells you that your name, '+S.nm6.l+', means '+S.nm6.mean.en+'. She says that as long as someone speaks your name, you live on, even after death.'),
 n:X('ชื่ออียิปต์ส่วนใหญ่มีความหมาย และมักเอ่ยถึงเทพ เช่น อาเมนโฮเทป แปลว่า “เทพอามุนทรงพอพระทัย” อักษรภาพของชื่อคุณในเกมนี้เป็นการสะกดแบบประมาณ ในการเขียนจริง ชื่อเทพมักถูกเขียนไว้ข้างหน้าเสมอเพื่อเป็นเกียรติ แม้จะออกเสียงทีหลัง','Most Egyptian names had meanings and often named a god: Amenhotep means “Amun is satisfied”. The hieroglyphs of your name in this game are an approximate spelling. In real writing the god’s name was usually written first, out of respect, even when it was spoken last.'),
 o:[opt(X('ภูมิใจในชื่อของตัวเอง','Be proud of your name'),S=>{fx({b:3,so:2});return X('คุณพูดชื่อตัวเองให้ทุกคนฟังทั้งวัน','You tell everyone your name all day long.')}),
    opt(X('ถามว่าเทพองค์นั้นเป็นใคร','Ask who that god is'),S=>{fx({kn:4});return X('แม่ชี้ให้ดูรูปเทพบนผนังวิหาร และเล่าเรื่องของเทพองค์นั้นจนมืด','Your mother shows you the god on the temple wall and tells you stories until dark.')}),
    opt(X('ถามว่าพ่อชื่อว่าอะไร และแปลว่าอะไร','Ask what your father’s name means'),S=>{fx({b:3,kn:2});return X('พ่อชื่อ '+S.nm6.fa.th+' แปลว่า '+S.nm6.fa.mean.th+' คุณจำชื่อของพ่อ ปู่ และทวดได้ครบ','Your father is '+S.nm6.fa.l+', which means '+S.nm6.fa.mean.en+'. You learn the names of your father, grandfather and great-grandfather by heart.')})]},
{id:'c6_croc',deck:'child',w:4,ch:6,a:[4,11],t:X('ดวงตาในน้ำตื้น','Eyes in the shallows'),
 x:X('คุณตามแม่ไปตักน้ำที่ริมแม่น้ำ แล้วเห็นดวงตาสองดวงกับจมูกยาวๆ โผล่อยู่เหนือน้ำตื้น ห่างไปไม่กี่ก้าว','You go with your mother to fetch water and see two eyes and a long snout above the shallows, a few steps away.'),
 n:X('จระเข้ไนล์ยาวได้ถึงราว 5 เมตร และฆ่าคนจำนวนมากริมแม่น้ำ ชาวอียิปต์ห้อยเครื่องรางและท่องคาถากันจระเข้ ภาพในสุสานแสดงคนเลี้ยงวัวยื่นนิ้วชี้ไปที่น้ำพร้อมท่องคาถา ขณะต้อนฝูงวัวข้ามคลอง ทุกวันนี้ในอียิปต์ จระเข้เหลืออยู่แค่เหนือเขื่อนอัสวานขึ้นไป','Nile crocodiles grow to about 5 metres and killed many people at the river. Egyptians wore amulets and recited spells against them; tomb scenes show herdsmen pointing a finger at the water and chanting as their cattle cross a channel. Today crocodiles live in Egypt only above the Aswan Dam.'),
 o:[opt(X('ค่อยๆ ถอยหลังออกมา','Back away slowly'),S=>{fx({b:2,sv:2});return X('ดวงตาจมหายไปโดยไม่มีระลอกน้ำ แม่ลากคุณกลับ และไม่ยอมปล่อยมือคุณทั้งวัน','The eyes sink without a ripple. Your mother pulls you back and does not let go of your hand all day.')}),
    opt(X('ขว้างก้อนหินใส่','Throw a stone at it'),S=>{if(rnd()<.45){fx({h:-4});return X('จระเข้พุ่งขึ้นมาจากน้ำ คุณล้มถลอกทั้งแขนขาตอนวิ่งหนี แต่รอดมาได้','The crocodile surges out of the water. You fall and scrape your knees running, but you get away.')}fx({so:2});return X('จระเข้ไถลลงน้ำลึกไป เด็กคนอื่นมองคุณอย่างทึ่ง','The crocodile slides into deep water. The other children stare at you in awe.')}),
    opt(X('ตะโกนเตือนเด็กคนอื่น','Shout to warn the other children'),S=>{fx({so:3,p:1});return X('เด็กๆ ปีนขึ้นตลิ่งกันหมด แม่ของเด็กคนหนึ่งให้ขนมน้ำผึ้งคุณเป็นรางวัล','The children scramble up the bank. One of their mothers gives you a honey cake.')})]},
{id:'c6_hippo',deck:'child',w:4,ch:6,a:[6,13],cond:S=>S.field>0,t:X('ฮิปโปในนาข้าว','A hippo in the field'),
 x:X('กลางดึก ฮิปโปตัวใหญ่ขึ้นจากแม่น้ำมาที่นาของครอบครัว และเริ่มกินต้นข้าวสาลีที่เพิ่งงอก','In the middle of the night a huge hippopotamus climbs out of the river into your family’s field and starts eating the young wheat.'),
 n:X('ฮิปโปขึ้นบกมากินพืชตอนกลางคืน และทำลายนาได้มาก ตำราของนักเรียนอาลักษณ์ในราชอาณาจักรใหม่เล่าความลำบากของชาวนาว่า “หนอนกินข้าวไปครึ่งหนึ่ง ฮิปโปกินส่วนที่เหลือ” ฮิปโปเป็นสัตว์ใหญ่ที่อันตรายที่สุดชนิดหนึ่งในแอฟริกาจนถึงวันนี้ ส่วนในอียิปต์ ฮิปโปตัวสุดท้ายถูกฆ่าในต้นศตวรรษที่ 19','Hippos come ashore at night to graze and could wreck a field. A New Kingdom school text describes the farmer’s misery: “the worm has taken half the grain, the hippopotamus has eaten the rest”. Hippos are still among the most dangerous large animals in Africa. In Egypt the last ones were killed in the early 1800s.'),
 o:[opt(X('ตีหม้อไล่กับพ่อ','Bang pots with your father to drive it off'),S=>{if(rnd()<.8){fx({b:3,f:-2});return X('ฮิปโปคำรามแล้วเดินหนักๆ กลับลงแม่น้ำ ครึ่งหนึ่งของแปลงยังเหลืออยู่','The hippo bellows and lumbers back into the river. Half the plot is saved.')}fx({h:-6});S.inj=1;return X('ฮิปโปหันมาวิ่งใส่ พ่อดึงคุณหลบทัน แต่ข้อเท้าคุณพลิก','The hippo turns and charges. Your father pulls you aside just in time, but you twist your ankle.')}),
    opt(X('ซ่อนอยู่ในบ้าน','Hide in the house'),S=>{fx({f:-6});return X('เช้าวันรุ่งขึ้น นาแปลงนั้นเหลือแต่รอยเท้ากลมใหญ่และโคลน','By morning the plot is nothing but huge round footprints and mud.')}),
    opt(X('จุดคบไฟรอบนา','Light torches around the field'),S=>{fx({kn:3,f:-3});return X('ฮิปโปไม่ชอบไฟ มันยืนมองอยู่นาน แล้วค่อยๆ กลับลงน้ำ ตั้งแต่นั้นพ่อจุดคบไฟทุกคืน','The hippo does not like the fire. It stares a long while, then slips back into the water. Your father lights torches every night after that.')})]},
{id:'c6_taweret',deck:'child',w:3,ch:6,a:[4,11],cond:S=>S.cls!=='elite'||rnd()<.5,t:X('อิฐแห่งการคลอด','The birth bricks'),
 x:X('แม่ของคุณใกล้คลอดแล้ว ผู้หญิงในบ้านตั้งอิฐคลอดสองก้อนให้แม่นั่ง และแขวนเครื่องรางรูปเทพีฮิปโปไว้เหนือที่นอน','Your mother is about to give birth. The women of the house set out two birth bricks for her to squat on, and hang a little hippo-goddess amulet over the bed.'),
 n:X('เทพีทาเวเรตมีร่างเป็นฮิปโปตั้งท้อง มีขาสิงโตและหางจระเข้ คุ้มครองแม่และทารก เช่นเดียวกับเทพเบสที่เป็นคนแคระ ชาวอียิปต์คลอดลูกในท่านั่งยองบนอิฐ อิฐคลอดที่มีภาพวาดจากราชอาณาจักรกลางชิ้นหนึ่งพบที่อไบดอส การคลอดเป็นสาเหตุการตายสำคัญของผู้หญิง','The goddess Taweret was a pregnant hippo with lion’s paws and a crocodile’s tail, who protected mothers and babies, as did the dwarf god Bes. Egyptian women gave birth squatting on bricks; a painted Middle Kingdom birth brick was found at Abydos. Childbirth was a major cause of death for women.'),
 o:[opt(X('จับมือแม่ไว้','Hold your mother’s hand'),S=>{fx({b:5});return X('แม่บีบมือคุณแน่นจนเจ็บ แล้วเสียงร้องของน้องก็ดังขึ้น','Your mother squeezes your hand until it hurts, and then the baby cries.')}),
    opt(X('วาดรูปเทพีทาเวเรตบนผนัง','Draw Taweret on the wall'),S=>{fx({cr:3,b:2});return X('รูปฮิปโปของคุณดูเหมือนวัวอ้วน แต่ผู้หญิงทุกคนบอกว่าเทพีต้องชอบแน่','Your hippo looks like a fat cow, but all the women say the goddess will surely like it.')}),
    opt(X('วิ่งไปตามหมอตำแย','Run for the midwife'),S=>{fx({so:3,sv:1});return X('คุณวิ่งเร็วที่สุดในชีวิต หมอตำแยมาทันพอดี','You run faster than ever in your life, and the midwife arrives just in time.')})]},
{id:'c6_school',deck:'child',w:4,ch:6,a:[6,10],cond:S=>!!S.schOK,t:X('วันแรกที่โรงเรียนอาลักษณ์','First day at the scribal school'),
 x:X('ครูให้คุณจุ่มก้านกกลงในหมึก แล้วคัดตัวอักษรลงบนแผ่นไม้ฉาบปูนขาวซ้ำไปซ้ำมา ครูพูดว่า “หูของเด็กอยู่ที่หลัง เขาจะฟังก็ต่อเมื่อถูกตี”','The teacher has you dip a reed pen in ink and copy signs onto a plastered wooden board, over and over. He says, “A boy’s ear is on his back: he listens when he is beaten.”'),
 n:X('นักเรียนอาลักษณ์ฝึกเขียนบนเศษหินปูน เศษหม้อ และแผ่นไม้ฉาบปูน เพราะกระดาษปาปิรุสแพง อักษรภาพไฮโรกลิฟใช้บนอนุสาวรีย์ ส่วนในชีวิตประจำวันใช้อักษรเฮียราติกที่เขียนเร็วกว่า คำพูดเรื่องหูของเด็กมาจากตำราของนักเรียนในราชอาณาจักรใหม่','Scribal pupils practised on limestone flakes, potsherds and plastered boards, because papyrus was costly. Hieroglyphs were for monuments; for daily writing scribes used a faster cursive, hieratic. The saying about the boy’s ear comes from a New Kingdom school text.'),
 o:[opt(X('คัดลอกอย่างตั้งใจทุกตัว','Copy every sign with care'),S=>{S.lit+=6;fx({kn:3});return X('ลายมือของคุณยังโย้ แต่ครูพยักหน้า','Your hand still wobbles, but the teacher nods.')}),
    opt(X('แอบวาดรูปแมวที่ขอบแผ่น','Secretly draw a cat in the margin'),S=>{fx({b:4});if(rnd()<.5){fx({h:-2});return X('ครูเห็นเข้า คุณโดนไม้เรียว แต่เพื่อนทั้งห้องหัวเราะ','The teacher sees it. You get the cane, but the whole class laughs.')}return X('ไม่มีใครเห็น ตอนเย็นครูลบแผ่นไม้ให้ขาวเพื่อใช้ใหม่ แมวของคุณหายไปพร้อมกับตัวหนังสือ','No one sees. In the evening the board is whitewashed for reuse, and your cat vanishes with the writing.')}),
    opt(X('ถามว่าตัวอักษรแต่ละตัวหมายถึงอะไร','Ask what each sign means'),S=>{S.lit+=4;fx({kn:5});return X('ครูบอกว่ารูปภาพบางตัวแทนเสียง เช่น รูปนกฮูกคือเสียง “ม” คุณนั่งมองนกฮูกบนหลังคาทั้งเย็น','The teacher says some pictures stand for sounds: the owl is “m”. You spend the evening staring at the owls on the roof.')})]},
{id:'c6_satire',deck:'child',w:3,ch:6,a:[9,13],cond:S=>!!S.schOK&&S.done.c6_school!=null&&era6(S.ya)!=='ed'&&era6(S.ya)!=='ok',t:X('เสียดสีอาชีพ','The Satire of the Trades'),
 x:X('ครูอ่านตำราให้ฟังว่า “ข้าเห็นช่างทองแดงที่ปากเตาหลอม นิ้วของเขาเหมือนหนังจระเข้ เขาเหม็นกว่าไข่ปลา” จบด้วยคำว่า “จงเป็นอาลักษณ์ แล้วเจ้าจะไม่ต้องแบกหาม”','The teacher reads aloud: “I have seen the coppersmith at the mouth of his furnace; his fingers are like crocodile skin, and he stinks worse than fish roe.” It ends: “Be a scribe, and you will be spared hard labour.”'),
 n:X('“เสียดสีอาชีพ” หรือคำสอนของเคตี เป็นตำราจากราชอาณาจักรกลาง ที่นักเรียนอาลักษณ์คัดลอกกันต่อมานับพันปี เยาะเย้ยงานทุกอย่าง ตั้งแต่ช่างโลหะ ชาวนา ไปจนถึงคนซักผ้า เพื่อให้นักเรียนตั้งใจเรียน ข้อความแปลแบบสรุป','The Satire of the Trades, or Teaching of Khety, is a Middle Kingdom text that scribal pupils copied for a thousand years. It mocks every job, from smith and farmer to washerman, to make pupils study hard. The quotation is paraphrased.'),
 o:[opt(X('หัวเราะไปกับเพื่อนๆ','Laugh along with the others'),S=>{fx({b:3,so:2});return X('ทั้งห้องหัวเราะจนครูต้องตีโต๊ะ','The whole class laughs until the teacher bangs the table.')}),
    opt(X('นึกถึงพ่อที่ทำนา','Think of your father, who farms'),S=>{fx({kn:2,b:-1});return X('คืนนั้นคุณมองมือของพ่อนานๆ แล้วตั้งใจคัดลอกหนักขึ้นอีก','That night you look a long time at your father’s hands, and copy harder than ever.')}),
    opt(X('ท่องจำให้ได้ทั้งบท','Learn the whole text by heart'),S=>{S.lit+=5;fx({kn:4});return X('คุณท่องได้ทั้งบท และใช้มันแกล้งเพื่อนทุกครั้งที่เขาบ่น','You learn it all, and quote it at your friends whenever they complain.')})]},
{id:'c6_senet',deck:'child',w:3,ch:6,a:[6,12],t:X('กระดานเซเนต','The senet board'),
 x:X('ปู่หยิบกระดานที่มีสามสิบช่องออกมา โยนไม้แบนสี่อัน แล้วสอนคุณเดินหมากไปตามช่อง','Your grandfather brings out a board of thirty squares, throws four flat sticks, and teaches you to move the pieces along the squares.'),
 n:X('เซเนตเป็นเกมกระดานที่เก่าแก่ที่สุดเกมหนึ่ง พบในสุสานตั้งแต่ราว 3000 ปีก่อนคริสตกาล ในสุสานของตุตันคาเมนมีกระดานเซเนตหลายชุด ในราชอาณาจักรใหม่ เกมนี้ถูกมองว่าเป็นการเดินทางของวิญญาณผ่านโลกหลังความตาย','Senet is one of the oldest board games, found in burials from about 3000 BCE; Tutankhamun’s tomb held several boards. By the New Kingdom it was seen as the soul’s journey through the afterlife.'),
 o:[opt(X('เล่นเอาชนะ','Play to win'),S=>{fx({kn:2,b:2});return rnd()<.5?X('คุณชนะ ปู่หัวเราะแล้วขอเล่นอีกตา','You win. Your grandfather laughs and demands another game.'):X('ปู่ชนะทุกตา แต่สอนเคล็ดลับให้หนึ่งอย่าง','Your grandfather wins every game, but teaches you one trick.')}),
    opt(X('แกล้งแพ้ให้ปู่','Let your grandfather win'),S=>{fx({b:4,so:2});return X('ปู่รู้ทัน แต่ทำเป็นไม่รู้ และยิ้มทั้งเย็น','He knows, but pretends not to, and smiles all evening.')}),
    opt(X('ถามว่าช่องสุดท้ายหมายถึงอะไร','Ask what the last square means'),S=>{fx({kn:4});return X('ปู่บอกว่าเป็นทางไปสู่ทุ่งต้นอ้อของโอซิริส ที่ที่ข้าวขึ้นสูงกว่าคน','He says it is the way to the Field of Reeds of Osiris, where the wheat grows taller than a man.')})]},
/* ----- youth ----- */
corvee6('y6_corvee','youth',[15,19]),
{id:'y6_cross',deck:'youth',w:4,ch:6,a:[12,30],cond:S=>herdTot()>0||S.car==='herder',t:X('ต้อนวัวข้ามคลอง','Driving the cattle across the channel'),
 x:X('ต้องต้อนฝูงวัวข้ามคลองไปทุ่งหญ้าอีกฝั่ง น้ำลึกถึงอก และเมื่อวานมีคนเห็นจระเข้แถวนี้','You must drive the cattle across a channel to the pasture on the other side. The water is chest-deep, and yesterday someone saw a crocodile here.'),
 n:X('ภาพในสุสานยุคราชอาณาจักรเก่า เช่นสุสานของตี ที่ซักการา แสดงคนเลี้ยงวัวแบกลูกวัวข้ามน้ำ ลูกวัวหันกลับไปมองแม่ ขณะที่อีกคนชี้นิ้วไปที่จระเข้ใต้น้ำและท่องคาถา','Old Kingdom tomb scenes, such as in the tomb of Ti at Saqqara, show a herdsman carrying a calf through the water while it looks back at its mother, and another pointing at a crocodile below and chanting a spell.'),
 o:[opt(X('ชี้นิ้วไปที่น้ำแล้วท่องคาถาแบบคนแก่','Point at the water and chant the spell like the old herdsmen'),S=>{if(rnd()<.8){fx({b:3,p:1});return X('ฝูงวัวข้ามไปได้ครบทุกตัว คุณเริ่มเชื่อว่าคาถาได้ผล','Every animal crosses safely. You begin to believe the spell works.')}const k=Object.keys(S.herd).find(k=>S.herd[k]>0);if(k)addHerd(k,-1);fx({b:-5});return X('น้ำกลางคลองปั่นป่วนขึ้นมา ลูกวัวตัวหนึ่งถูกลากหายไปต่อหน้าต่อตา','The water boils in mid-channel, and a calf is dragged under before your eyes.')}),
    opt(X('แบกลูกวัวขึ้นบ่า','Carry the calf on your shoulders'),S=>{fx({h:-2,sv:3});return X('ลูกวัวร้องหาแม่ตลอดทาง แม่วัวว่ายตามมาติดๆ ทั้งฝูงตามมา','The calf bawls for its mother all the way; she swims close behind, and the whole herd follows.')}),
    opt(X('รอจนจระเข้ไปที่อื่น','Wait until the crocodile moves on'),S=>{fx({f:-2,kn:2});return X('คุณรอจนบ่ายจึงเห็นมันไปนอนอาบแดดอีกฝั่ง แล้วรีบข้าม','You wait until afternoon, see it basking far off, and hurry across.')})]},
{id:'y6_hunt',deck:'youth',w:3,ch:6,a:[14,26],cond:S=>S.cls==='elite'||S.car==='fisher',t:X('ล่าฮิปโปในบึง','The hippo hunt in the marsh'),
 x:X('ขุนนางเจ้าของที่ดินออกล่าฮิปโปบนเรือกกปาปิรุส คุณถูกเลือกให้ไปด้วย ในมือมีฉมวกที่ผูกเชือกยาว','The lord of the estate goes hunting hippos from a papyrus skiff, and you are chosen to go along, holding a harpoon on a long rope.'),
 n:X('ภาพในสุสานขุนนางมักแสดงเจ้าของสุสานแทงฮิปโปจากเรือกก ฮิปโปเป็นสัญลักษณ์ของเทพเซทและความวุ่นวาย การฆ่ามันจึงเหมือนฮอรัสปราบความชั่ว แต่การล่าจริงอันตรายมาก ฮิปโปพลิกเรือและกัดคนตายได้ง่ายๆ','Nobles’ tomb scenes often show the owner harpooning a hippo from a reed boat. The hippo stood for the god Seth and chaos, so killing it echoed Horus defeating disorder. Real hunts were very dangerous: a hippo could easily overturn a boat and kill a man.'),
 o:[opt(X('พุ่งฉมวกเอง','Throw the harpoon yourself'),S=>{if(rnd()<.55){fx({p:6,sv:4});ms(X('ล่าฮิปโปในบึงปาปิรุส','Hunted a hippo in the papyrus marsh'));return X('ฉมวกปักเข้า ฮิปโปลากเรือไปจนทุกคนช่วยกันดึงเชือก ขุนนางตบไหล่คุณต่อหน้าทุกคน','The harpoon strikes. The hippo drags the boat until everyone hauls the rope together, and the lord claps your shoulder in front of them all.')}fx({h:-12});S.inj=1;return X('ฮิปโปพลิกเรือคว่ำ คุณจมน้ำเกือบตาย และถูกฟันของมันเฉี่ยวขา','The hippo overturns the boat. You nearly drown, and its tusk gashes your leg.')}),
    opt(X('จับเชือกอยู่ท้ายเรือ','Hold the rope at the stern'),S=>{fx({sv:2,b:2});return X('เชือกบาดมือคุณจนเลือดออก แต่เรือไม่ล่ม','The rope cuts your palms bloody, but the boat stays upright.')}),
    opt(X('ขอไม่ไป','Ask to stay behind'),S=>{fx({p:-2});return X('ขุนนางเลิกคิ้ว แล้วหาคนอื่นไปแทน','The lord raises an eyebrow and picks someone else.')})]},
{id:'y6_marry',deck:'youth',w:4,ch:6,a:[15,21],cond:S=>!S.partner,t:X('สร้างบ้านด้วยกัน','Founding a house'),
 x:X('ครอบครัวของคุณกับอีกครอบครัวคุยกันเรื่องให้คุณสองคนอยู่ด้วยกัน ในอียิปต์ ไม่มีพิธีในวิหาร แค่ย้ายไปอยู่บ้านเดียวกัน ก็ถือว่า “สร้างบ้าน” แล้ว','Your family and another are talking of you two living together. In Egypt there is no temple ceremony: moving into one house is “founding a house”.'),
 n:X('การแต่งงานในอียิปต์เป็นเรื่องของครอบครัว ไม่ใช่ศาสนา ในยุคหลังมีสัญญาที่คุ้มครองทรัพย์สินของภรรยา ภรรยามีสิทธิ์หย่า และในราชอาณาจักรใหม่ เมื่อหย่ามักได้ทรัพย์สินร่วมราวหนึ่งในสาม คู่รักในบทกวีเรียกกันว่า “พี่ชาย” และ “น้องสาว”','Marriage in Egypt was a family matter, not a religious rite. Later, marriage contracts protected the wife’s property; wives could divorce, and in the New Kingdom often kept about a third of the joint property. In love poems lovers call each other “brother” and “sister”.'),
 o:[opt(X('ย้ายไปอยู่บ้านเดียวกัน','Move in together'),S=>{S.partner=1;fx({b:6});ms(X('สร้างบ้านกับคนที่รัก','Founded a house with someone you love'));return X('ห้องเล็กๆ ที่มีเตาขนมปังและเสื่อกก ตอนนี้เป็นบ้านของคุณสองคน','A small room with a bread oven and a reed mat is now your house.')}),
    opt(X('แต่งเพลงรักให้ก่อน','First, compose a love song'),S=>{if(rnd()<.7){S.partner=1;fx({b:8,cr:2});ms(X('สร้างบ้านกับคนที่รัก','Founded a house with someone you love'));return X('คุณร้องว่า “ใจของฉันกระโดดเมื่อคิดถึงเธอ” ทั้งหมู่บ้านล้อคุณไปหลายเดือน แต่คำตอบคือใช่','You sing that your heart leaps when you think of them. The whole village teases you for months, but the answer is yes.')}fx({b:-3});return X('เพลงของคุณทำให้ทุกคนหัวเราะ ยกเว้นคนที่คุณร้องให้ฟัง','Your song makes everyone laugh, except the one you sang it to.')}),
    opt(X('ขอรอไปก่อน','Ask to wait'),S=>{S.later=1;fx({b:-1});return X('ครอบครัวบ่น แต่ยอมรอ','The families grumble, but agree to wait.')})]},
/* ----- adulthood ----- */
corvee6('a6_corvee','adult',[20,40]),
{id:'a6_letter',deck:'adult',w:3,ch:6,a:[22,50],cond:S=>era6(S.ya)!=='ed',t:X('จดหมายถึงคนที่บ้าน','A letter home'),
 x:X('คุณต้องไปทำงานที่ที่ดินไกลบ้านหลายเดือน มีข่าวมาว่าคนในบ้านทะเลาะกันเรื่องส่วนแบ่งข้าว และมีคนรังแกคนใหม่ในครอบครัว','You must work at a distant estate for months. Word comes that the household is quarrelling over grain rations, and someone is bullying the newest member of the family.'),
 n:X('จดหมายของเฮกานัคต์ ราว 1950 ปีก่อนคริสตกาล เป็นจดหมายของชาวนาและนักบวชที่เขียนกลับบ้าน ระบุว่าใครควรได้ข้าวเท่าไร และต่อว่าคนในบ้านที่ไม่ดีกับภรรยาใหม่ของเขา จดหมายพบในสุสานที่ธีบส์ อาจไม่เคยถูกส่งถึงมือผู้รับ อกาธา คริสตี้นำเรื่องนี้ไปแต่งนิยายสืบสวนเรื่อง “ความตายมาถึงในตอนจบ”','The Heqanakht letters, about 1950 BCE, were written home by a farmer-priest. They say exactly how much grain each person should get, and scold the household for mistreating his new wife. Found in a tomb at Thebes, they may never have been delivered. Agatha Christie based her mystery Death Comes as the End on them.'),
 o:[wOpt6(X('เขียนจดหมายกำหนดส่วนแบ่งให้ชัด','Write a letter setting out every ration'),S=>{const w=doWrite6(S,'letter');fx({b:3,p:2});return w?X('คุณเขียนเองว่าใครได้ข้าวกี่กระสอบ และปิดท้ายว่า “อย่าให้ใครรังแกเธออีก”','You write out who gets how many sacks, ending: “Let no one mistreat her again.”'):X('คุณจ้างอาลักษณ์เขียน และให้เขาอ่านทวนสามรอบ','You hire a scribe to write it, and have him read it back three times.')}),
    opt(X('ขอลากลับบ้าน','Ask for leave to go home'),S=>{fx({b:4,f:-3});return X('คุณเดินทางกลับห้าวัน เสียค่าจ้างไปหลายวัน แต่บ้านสงบลง','It takes five days to get home and costs you wages, but the house calms down.')}),
    opt(X('ปล่อยให้พวกเขาจัดการกันเอง','Let them sort it out'),S=>{fx({b:-4});return X('เมื่อคุณกลับมา ทุกคนไม่พูดกันมาหลายเดือนแล้ว','When you return, nobody has spoken to anybody for months.')})]},
{id:'a6_lend',a:[22,60],w:1.2,ch:6,cond:S=>S.ag>=3&&!S.lent&&S.ppl.some(p=>!p.dead&&p.age>=16&&p.k!=='partner'),t:X('ขอยืมข้าว','Asked for a loan of grain'),
 xf:S=>{const p=S.ppl.find(p=>!p.dead&&p.age>=16&&p.k!=='partner');S.lentTo=p;return PX(p,'{p}มาขอยืมข้าวสองกระสอบ บอกว่าจะคืนหลังเก็บเกี่ยว','{p} asks to borrow two sacks of grain, promising to repay after harvest.')},
 n:X('ที่เดร์เอล-เมดินา ชาวบ้านจดหนี้กันบนเศษหินและเศษหม้อ บางรายการบอกว่าใครยืมอะไร มูลค่ากี่เดเบน และใครเป็นพยาน','At Deir el-Medina villagers noted debts on flakes of stone and potsherds, sometimes saying who borrowed what, its value in deben, and who witnessed it.'),
 o:[wOpt6(X('ให้ยืม และจดไว้ต่อหน้าพยาน','Lend it, and note it before witnesses'),S=>{const w=doWrite6(S,'account');S.ag-=2;S.lent={p:S.lentTo,a:S.age,c:1};return w?X('คุณเขียนชื่อผู้ยืม ข้าวสองกระสอบ และชื่อพยานสองคนลงบนเศษหม้อ','You write the borrower’s name, two sacks of grain and two witnesses on a potsherd.'):X('คุณจ้างอาลักษณ์จดไว้ พร้อมชื่อพยานสองคน','You have a scribe note it down, with two witnesses.')}),
    opt(X('ให้ยืมโดยไม่ต้องจด','Lend it on trust'),S=>{S.ag-=2;S.lent={p:S.lentTo,a:S.age,c:0};S.lentTo.tr=Math.min(100,S.lentTo.tr+8);return PX(S.lentTo,'{p}กอดคุณ และสัญญาว่าจะคืนแน่นอน','{p} embraces you and swears to repay.')}),
    opt(X('ปฏิเสธ','Refuse'),S=>{S.lentTo.tr-=8;return PX(S.lentTo,'{p}เดินกลับไปเงียบๆ','{p} walks away in silence.')})]},
{id:'a6_collect',a:[23,70],w:6,ch:6,cond:S=>S.lent&&!S.lent.done&&S.age-S.lent.a>=2,t:X('ทวงหนี้','Collecting the debt'),
 xf:S=>PX(S.lent.p,'สองปีผ่านไปแล้ว {p}ยังไม่คืนข้าวสองกระสอบ และทำเป็นไม่เห็นคุณที่ตลาด','Two years have passed. {p} has not returned the two sacks of grain and pretends not to see you at the market.'),
 n:hireNote6,
 o:[wOpt6(X('เขียนจดหมายทวงบนกระดาษปาปิรุส','Write a demand letter on papyrus'),S=>{const p=S.lent.p;S.lent.done=1;doWrite6(S,'letter');
      if(p.dead){return PX(p,'จดหมายไปถึงบ้านของ{p} แต่เขาเพิ่งตาย ลูกชายของเขาคืนข้าวให้หนึ่งกระสอบด้วยความละอาย','The letter reaches {p}’s house, but he has just died. His son returns one sack, ashamed.')}
      if(rnd()<.55+(p.tr-50)/200){S.ag+=3;p.tr=Math.max(0,p.tr-5);return PX(p,'จดหมายของคุณขึ้นต้นว่า “ขอให้ท่านมีชีวิต ความรุ่งเรือง และสุขภาพดี” แล้วจึงทวงข้าว ไม่กี่วันต่อมา{p}ส่งข้าวคืนมาพร้อมดอกเบี้ย','Your letter opens, “Life, prosperity and health to you!” before it asks for the grain. A few days later {p} sends it back with interest.')}
      p.tr-=10;return PX(p,'{p}ตอบกลับมาว่าปีนี้น้ำไนล์ขึ้นน้อย ขอผัดไปก่อน','{p} replies that the Nile rose too little this year, and begs for more time.')}),
    Object.assign(opt(X('ฟ้องต่อศาลหมู่บ้าน พร้อมพยาน','Take it to the village court, with your witnesses'),S=>{S.lent.done=1;S.ag+=3;fx({p:2});return PX(S.lent.p,'ศาลฟังพยานของคุณ แล้วสั่งให้{p}สาบานในนามพระราชาว่าจะคืนข้าวภายในเดือนนี้','The court hears your witnesses and orders {p} to swear by the king’s name to repay within the month.')}),{lockF:S=>!S.lent.c,lockT:X('ต้องมีบันทึกและพยาน','You need a written note and witnesses')}),
    opt(X('ยกหนี้ให้','Forgive the debt'),S=>{S.lent.done=1;S.lent.p.tr=Math.min(100,S.lent.p.tr+20);fx({b:4});return PX(S.lent.p,'{p}ร้องไห้ และจะไม่ลืมน้ำใจของคุณ','{p} weeps, and will never forget your kindness.')})]},
{id:'a6_oracle',a:[22,65],w:3,ch:6,cond:S=>era6(S.ya)==='nk'&&['dem','the'].includes(S.rg),t:X('ถามเทพ','Asking the god'),
 x:X('ผ้าลินินชิ้นดีของคุณหายไป และคุณสงสัยเพื่อนบ้าน วันนี้นักบวชจะแห่รูปเคารพของพระเจ้าอาเมนโฮเทปที่ 1 ผ่านหมู่บ้าน ใครมีคำถามก็ถามได้','Your best piece of linen has gone missing, and you suspect a neighbour. Today the priests carry the statue of the deified King Amenhotep I through the village; anyone may put a question to it.'),
 n:X('ในราชอาณาจักรใหม่ ผู้คนถามคำถามกับรูปเคารพของเทพที่นักบวชแบกบนเรือจำลองในขบวนแห่ รูปเคารพ “ตอบ” ด้วยการโน้มไปข้างหน้าหรือถอยหลัง ที่เดร์เอล-เมดินา ชาวบ้านถามพระเจ้าอาเมนโฮเทปที่ 1 ผู้ก่อตั้งหมู่บ้าน เรื่องตั้งแต่ขโมยไปจนถึงกรรมสิทธิ์บ้าน','In the New Kingdom people put questions to a god’s statue carried in procession on a model boat. It “answered” by lurching forward or back. At Deir el-Medina villagers asked the deified Amenhotep I, the village’s founder, about everything from thefts to who owned a house.'),
 o:[opt(X('ถามว่าเพื่อนบ้านเอาไปหรือไม่','Ask whether your neighbour took it'),S=>{if(rnd()<.5){fx({p:2,b:-2});return X('รูปเคารพโน้มไปข้างหน้า เพื่อนบ้านหน้าซีด แล้วคืนผ้าให้ในคืนนั้น แต่ไม่เคยทักคุณอีกเลย','The statue lurches forward. Your neighbour turns pale and returns the linen that night, but never greets you again.')}fx({b:-3});return X('รูปเคารพถอยหลัง เพื่อนบ้านไม่ได้เอาไป คุณต้องเดินไปขอโทษ','The statue moves back: your neighbour did not take it. You must go and apologise.')}),
    opt(X('อ่านชื่อทุกบ้านให้เทพเลือก','Read out every household and let the god choose'),S=>{fx({so:2,kn:2});return X('รูปเคารพหยุดหน้าบ้านหลังหนึ่งที่ไม่มีใครคาดคิด และเด็กในบ้านนั้นยอมรับทั้งน้ำตา','The statue halts at a house no one expected, and the child there confesses in tears.')}),
    opt(X('ไม่ถาม ปล่อยมันไป','Ask nothing, and let it go'),S=>{fx({b:2});return X('คุณทอผ้าผืนใหม่ และไม่มีใครต้องอับอาย','You weave a new cloth, and no one is shamed.')})]},
{id:'a6_strike',a:[18,70],w:9,ch:6,cond:S=>S.ya<=3184&&S.ya>=3178&&['dem','the'].includes(S.rg),t:X('“พวกเราหิว!”','“We are hungry!”'),
 x:X('ปันส่วนข้าวของคนงานสุสานหลวงมาช้าไปสิบแปดวันแล้ว ช่างทั้งหมู่บ้านวางเครื่องมือ เดินไปนั่งหลังวิหาร แล้วตะโกนว่า “พวกเราหิว!”','The royal tomb-workers’ grain rations are eighteen days late. The whole village’s craftsmen down tools, march out to sit behind the temple, and shout, “We are hungry!”'),
 n:X('ปาปิรุสแห่งตูรินบันทึกว่าในปีที่ 29 ของรัชกาลรามเสสที่ 3 ราว 1157 ปีก่อนคริสตกาล คนงานสุสานหลวงหยุดงานเพราะไม่ได้ปันส่วน มักถูกเรียกว่าการนัดหยุดงานครั้งแรกที่มีบันทึก อาลักษณ์ชื่ออาเมนนัคต์เป็นผู้บันทึก และในที่สุดคนงานก็ได้ข้าว','The Turin Strike Papyrus records that in year 29 of Ramesses III, about 1157 BCE, the royal tomb-workers stopped work because their rations had not come. It is often called the first recorded strike. The scribe Amennakht wrote it down, and in the end the workers got their grain.'),
 o:[opt(X('ไปนั่งประท้วงกับทุกคน','Sit down and protest with everyone'),S=>{fx({b:6,f:3,so:3});ms(X('ร่วมการนัดหยุดงานครั้งแรกที่มีบันทึกในประวัติศาสตร์','Joined the first recorded strike in history'));return X('คุณนั่งตากแดดทั้งวัน ร้องตะโกนจนเสียงแหบ สามวันต่อมา ข้าวก็มาถึง','You sit in the sun all day and shout yourself hoarse. Three days later the grain arrives.')}),
    opt(X('ทำงานต่อไป','Keep working'),S=>{fx({b:-5,p:1});return X('หัวหน้าชมคุณ แต่เพื่อนบ้านไม่ทักคุณอีกหลายเดือน','The foreman praises you, but your neighbours do not greet you for months.')}),
    wOpt6(X('เขียนคำร้องถึงขุนนางผู้ใหญ่','Write a petition to the vizier'),S=>{doWrite6(S,'letter');fx({p:4,kn:2});return X('คำร้องของคุณพูดถึงความหิว และพูดถึงมาอัต ความถูกต้องที่พระราชาต้องรักษา ขุนนางส่งข้าวมาให้ส่วนหนึ่งก่อน','Your petition speaks of hunger, and of Ma’at, the right order the king must keep. The vizier sends part of the grain at once.')})]},
{id:'a6_robbers',a:[20,65],w:6,ch:6,cond:S=>S.ya<=3140&&S.ya>=3110&&['dem','the'].includes(S.rg),t:X('ทองจากสุสานหลวง','Gold from a royal tomb'),
 x:X('ช่างหินคนหนึ่งกระซิบว่าเขากับพรรคพวกเจาะเข้าสุสานของกษัตริย์องค์เก่า ได้ทองมาเต็มกระสอบ ถ้าคุณช่วยขาย คุณจะได้ส่วนแบ่ง','A stonemason whispers that he and his gang broke into an old king’s tomb and took a sack of gold. If you help sell it, you get a share.'),
 n:X('ปาปิรุสบันทึกการสอบสวนสมัยรามเสสที่ 9 ราว 1110 ปีก่อนคริสตกาล มีคำสารภาพของช่างหินชื่ออาเมนปาเนเฟอร์ ที่เล่าว่าแก๊งของเขาเจาะเข้าสุสานของพระเจ้าโซเบคเอมซาฟที่ 2 กับพระมเหสี แล้วแบ่งทองกัน โจรปล้นสุสานมีโทษถึงตายด้วยการเสียบหลัก','Papyri record investigations under Ramesses IX, about 1110 BCE, including the confession of a stonemason named Amenpanefer, who told how his gang broke into the tomb of King Sobekemsaf II and his queen and divided the gold. Tomb robbers faced death by impalement.'),
 o:[opt(X('ปฏิเสธ และไม่พูดอะไร','Refuse, and say nothing'),S=>{fx({b:-1});return X('คุณนอนไม่หลับหลายคืน แต่เก็บปากเงียบ','You sleep badly for many nights, but keep silent.')}),
    opt(X('แจ้งเจ้าหน้าที่','Report it to the officials'),S=>{fx({p:6,b:-4});return X('แก๊งนั้นถูกจับ คุณต้องไปให้การ และหลายบ้านในหมู่บ้านมองคุณด้วยสายตาเย็นชา','The gang is arrested. You must testify, and several houses in the village look at you coldly.')}),
    opt(X('ช่วยขาย แลกส่วนแบ่ง','Help sell it for a share'),S=>{if(rnd()<.4){S.ag=0;fx({p:-12,b:-8,h:-10});S.yr+=.08;return X('คุณถูกจับพร้อมแก๊ง ถูกเฆี่ยนที่ฝ่าเท้า และเสียทุกอย่างที่มี ครอบครัวของคุณอับอายไปทั้งหมู่บ้าน','You are caught with the gang, beaten on the soles of your feet and stripped of everything. Your family is shamed before the whole village.')}S.ag+=8;fx({b:-3});return X('ทองแลกเป็นข้าว ผ้า และวัวได้มากมาย แต่คุณสะดุ้งทุกครั้งที่มีเจ้าหน้าที่เดินผ่าน','The gold buys plenty of grain, cloth and cattle, but you flinch whenever an official walks by.')})]},
{id:'a6_aten',a:[14,70],w:8,ch:6,cond:S=>S.ya<=3371&&S.ya>=3357,t:X('เทพในบ้าน','The gods in the house'),
 x:X('เจ้าหน้าที่ประกาศว่าให้บูชาเทพอาเทนเพียงองค์เดียว แต่ในห้องของคุณยังมีรูปเทพเบสและเทพีทาเวเรต ที่คุ้มครองเด็กๆ ในบ้านมาตลอด','Officials proclaim that only the Aten may be worshipped. But in your room stand little figures of Bes and Taweret, who have always protected the children of the house.'),
 n:X('นักโบราณคดีพบรูปเทพเบส ทาเวเรต และเครื่องรางของเทพองค์อื่นในบ้านคนธรรมดาที่อามาร์นา แสดงว่าผู้คนยังบูชาเทพเดิมกันในบ้าน แม้ในเมืองของเทพอาเทนเอง','Archaeologists found figures of Bes, Taweret and amulets of other gods in ordinary houses at Amarna, showing that people kept worshipping the old gods at home, even in the Aten’s own city.'),
 o:[opt(X('ซ่อนไว้ใต้เสื่อ','Hide them under the mat'),S=>{fx({b:3});return X('ทุกคืน คุณยังกระซิบกับเทพเบสก่อนนอน','Every night you still whisper to Bes before you sleep.')}),
    opt(X('ทุบทิ้งตามคำสั่ง','Smash them as ordered'),S=>{fx({p:3,b:-5});return X('ลูกของคุณร้องไห้ตอนเห็นเศษดินเผา คืนนั้นทั้งบ้านนอนไม่หลับ','Your child cries at the broken pieces, and no one in the house sleeps that night.')}),
    opt(X('บูชาทั้งอาเทนและเทพในบ้าน','Worship both the Aten and the house gods'),S=>{fx({b:2,so:2});return X('ตอนเช้าคุณยกมือรับแสงอาทิตย์ ตอนค่ำคุณถวายขนมให้เทพเบส ไม่มีใครรู้ว่าคุณคิดอะไร','At dawn you raise your hands to the sun; at dusk you leave a cake for Bes. No one knows what you really believe.')})]},
{id:'a6_doctor',a:[18,70],w:4,ch:6,cond:S=>!!S.sick||!!S.inj,t:X('ไปหาหมอ','Going to the physician'),
 x:X('คุณเจ็บหนักจนต้องไปหาหมอ หมอดูอาการ จดอะไรบางอย่างลงบนกระดาษปาปิรุส แล้วถามว่าจะรักษาด้วยยาหรือด้วยคาถา','You are ill enough to go to the physician. He examines you, notes something on papyrus, and asks whether you want medicine or a spell.'),
 n:X('หมออียิปต์มีชื่อเสียงไปทั่วโลกโบราณ ปาปิรุสเอ็ดวิน สมิธ ซึ่งคัดลอกราว 1600 ปีก่อนคริสตกาล บรรยายการบาดเจ็บ 48 กรณีตั้งแต่ศีรษะถึงกระดูกสันหลัง และบอกว่าแต่ละกรณีควรรักษาหรือไม่ หมอใช้น้ำผึ้งซึ่งฆ่าเชื้อได้ทาแผล ชาวอียิปต์ใช้ยาและคาถาควบคู่กันโดยไม่เห็นว่าขัดกัน','Egyptian doctors were famous across the ancient world. The Edwin Smith Papyrus, copied about 1600 BCE, describes 48 injuries from head to spine and says whether each should be treated. Physicians dressed wounds with honey, which kills bacteria. Egyptians used medicine and spells together and saw no conflict between them.'),
 o:[opt(X('ยา: น้ำผึ้งกับผ้าลินิน','Medicine: honey and linen'),S=>{fx({h:8});if(S.inj)S.inj=0;return X('หมอทาน้ำผึ้ง พันผ้าลินินสะอาด และสั่งให้กลับมาอีกสามวัน','The physician spreads honey, binds it in clean linen, and tells you to come back in three days.')}),
    opt(X('คาถาและเครื่องราง','A spell and an amulet'),S=>{fx({b:5,h:2});return X('หมอท่องคาถาเรียกเทพไอซิส แล้วผูกเครื่องรางรูปตาของฮอรัสไว้ที่ข้อมือคุณ','He chants a spell calling on Isis, and ties an Eye of Horus amulet to your wrist.')}),
    Object.assign(opt(X('ทั้งสองอย่าง','Both'),S=>{S.ag--;fx({h:8,b:4});if(S.inj)S.inj=0;return X('น้ำผึ้งสำหรับแผล คาถาสำหรับหัวใจ คุณรู้สึกดีขึ้นตั้งแต่เดินออกมา','Honey for the wound, a spell for the heart. You feel better before you are out of the door.')}),{lockF:S=>S.ag<1,lockT:X('ต้องมีของมูลค่า 1 เดเบน','Needs 1 deben in goods')})]},
{id:'a6_coffin',a:[30,55],w:3,ch:6,t:X('โลงศพไม้ทาสี','A painted coffin'),
 x:X('ช่างไม้ในหมู่บ้านทำโลงศพไม้ทาสีสวยงาม ราคาเท่ากับค่าจ้างคนงานหลายเดือน ครอบครัวต้องตัดสินใจว่าจะเก็บเงินไว้ซื้อหรือไม่','The village carpenter makes beautiful painted wooden coffins. One costs as much as many months of a workman’s pay, and your family must decide whether to save for one.'),
 n:X('บันทึกจากเดร์เอล-เมดินาแสดงว่าโลงศพและของในสุสานกินรายได้ของครอบครัวไปมาก หลายครอบครัวใช้โลงเก่าซ้ำ โดยขูดชื่อเดิมออกแล้วเขียนชื่อใหม่ สำหรับชาวอียิปต์ การเตรียมตัวตายไม่ใช่เรื่องเศร้า แต่เป็นการลงทุนเพื่อชีวิตนิรันดร์','Records from Deir el-Medina show coffins and tomb goods took a large share of a family’s income. Many reused old coffins, scraping off the old name and writing a new one. For Egyptians, preparing for death was not morbid but an investment in eternity.'),
 o:[Object.assign(opt(X('เก็บเงินซื้อโลงศพ','Save for the coffin'),S=>{S.ag-=3;S.tomb=1;fx({b:3});ms(X('มีโลงศพไม้ทาสีรอไว้','Bought a painted coffin for eternity'));return X('ช่างเขียนชื่อของคุณลงบนโลงด้วยหมึกสีดำ คุณไปดูมันทุกเดือน','The craftsman writes your name on it in black ink. You visit it every month.')}),{lockF:S=>S.ag<3,lockT:X('ต้องมีของมูลค่า 3 เดเบน','Needs 3 deben in goods')}),
    opt(X('ใช้เงินส่งลูกเรียนแทน','Spend it on the children’s schooling instead'),S=>{fx({b:2,p:1});S.kidsSch=1;return X('ลูกคนหนึ่งได้ไปเรียนกับอาลักษณ์ เขาอาจเขียนชื่อคุณได้สักวัน','One of your children goes to study with a scribe. One day they may write your name.')}),
    opt(X('หลุมในทรายก็พอแล้ว','A pit in the sand is enough'),S=>{fx({f:3});return X('คุณบอกว่าทรายร้อนจะรักษาร่างไว้เอง เหมือนบรรพบุรุษสมัยก่อน','You say the hot sand will keep your body, as it kept the ancestors.')})]},
{id:'a6_bod',a:[30,65],w:3,ch:6,cond:S=>era6(S.ya)==='nk'&&(S.lit>=50||S.ag>=3),t:X('คัมภีร์แห่งความตาย','A Book of the Dead'),
 x:X('ร้านของอาลักษณ์ในวิหารขายม้วนกระดาษปาปิรุสที่เขียนคาถาสำหรับโลกหลังความตายไว้พร้อมภาพสี เว้นช่องว่างไว้สำหรับเขียนชื่อผู้ซื้อ','The temple scribes’ workshop sells papyrus scrolls of spells for the afterlife, with painted pictures and blank spaces left for the buyer’s name.'),
 n:X('ม้วน “คัมภีร์แห่งความตาย” หลายม้วนถูกเขียนสำเร็จรูปไว้ก่อน แล้วค่อยเติมชื่อผู้ตายลงในช่องว่าง บางม้วนช่องว่างไม่เคยถูกเติมเลย คาถาบทที่ 125 มี “คำสารภาพว่าไม่ได้ทำผิด” เช่น “ข้าไม่ได้ขโมย… ข้าไม่ได้ย้ายหลักเขตที่นา…” ซึ่งผู้ตายต้องกล่าวต่อหน้าเทพ ก่อนหัวใจจะถูกชั่ง','Many Books of the Dead were written in advance, with the dead person’s name added in blank spaces later; in some the blanks were never filled. Spell 125 holds the “declaration of innocence”, such as “I have not stolen… I have not moved the boundary stone…”, which the dead recited before the gods before their heart was weighed.'),
 o:[Object.assign(opt(X('ซื้อม้วนยาวที่มีภาพสี','Buy a long scroll with paintings'),S=>{S.ag-=3;S.bod=2;fx({b:4,p:2});ms(X('มีคัมภีร์แห่งความตายที่มีชื่อของคุณ','Owned a Book of the Dead with your name in it'));return X('อาลักษณ์เติมชื่อของคุณลงในช่องว่างทุกช่อง คุณให้เขาอ่านให้ฟังทีละบรรทัด','The scribe fills your name into every blank, and you have him read it to you line by line.')}),{lockF:S=>S.ag<3,lockT:X('ต้องมีของมูลค่า 3 เดเบน','Needs 3 deben in goods')}),
    Object.assign(opt(X('คัดลอกเองทีละบท','Copy one yourself, spell by spell'),S=>{S.bod=1;S.papN+=3;S.papK.bod=1;fx({kn:5,b:3});ms(X('มีคัมภีร์แห่งความตายที่มีชื่อของคุณ','Owned a Book of the Dead with your name in it'));return X('ใช้เวลาหลายเดือน มือของคุณปวด แต่ทุกบรรทัดเป็นลายมือของคุณเอง','It takes months and your hand aches, but every line is in your own writing.')}),{lockF:S=>S.lit<50,lockT:X('ต้องอ่านเขียนได้คล่อง','You must read and write well')}),
    opt(X('แพงเกินไป','Too expensive'),S=>{fx({f:2});return X('คุณท่องคาถาสั้นๆ ที่แม่สอนไว้แทน','You recite the short spell your mother taught you instead.')})]},
{id:'a6_drunk',a:[18,60],w:3,ch:6,cond:S=>era6(S.ya)==='nk'||S.car==='brewer',t:X('เทศกาลแห่งความเมามาย','The Festival of Drunkenness'),
 x:X('คืนนี้เป็นเทศกาลของเทพีฮาธอร์ ทุกคนดื่มเบียร์จนเมา เพื่อระลึกถึงวันที่เบียร์สีแดงช่วยให้เทพีสิงโตสงบลง','Tonight is Hathor’s festival. Everyone drinks until they are drunk, to remember how red beer once calmed the lioness goddess.'),
 n:X('ในตำนาน “การทำลายล้างมนุษย์” เทพราส่งเทพีเซคเมตมาลงโทษมนุษย์ แล้วต้องหยุดเธอด้วยเบียร์ที่ย้อมเป็นสีแดงเหมือนเลือด เธอดื่มจนเมาแล้วกลายเป็นเทพีฮาธอร์ผู้อ่อนโยน หลักฐานจากวิหารเทพีมุตที่ธีบส์ แสดงว่าในราชอาณาจักรใหม่มีพิธีดื่มจนเมาจริง','In the myth of the Destruction of Mankind, Ra sends the lioness Sekhmet to punish humans, then stops her with beer dyed red like blood. She drinks herself drunk and becomes gentle Hathor. Evidence from the temple of Mut at Thebes shows that real rites of drunkenness were held in the New Kingdom.'),
 o:[opt(X('ดื่มจนเห็นเทพี','Drink until you see the goddess'),S=>{fx({b:6,h:-2});return X('คุณตื่นขึ้นตอนเช้าบนบันไดวิหาร ไม่รู้ว่าเห็นเทพีจริงหรือแค่ฝัน','You wake at dawn on the temple steps, unsure whether you saw the goddess or dreamed her.')}),
    opt(X('ดื่มนิดหน่อยแล้วดูแลเด็กๆ','Drink a little and watch the children'),S=>{fx({b:3,so:2});return X('คุณเป็นคนเดียวที่จำได้ว่าเกิดอะไรขึ้นบ้าง และเล่าให้ทุกคนฟังไปอีกหลายวัน','You are the only one who remembers what happened, and you tell everyone for days.')}),
    opt(X('หมักเบียร์แดงไปถวาย','Brew red beer for the goddess'),S=>{fx({cr:3,p:2});return X('คุณผสมดินแดงลงในเบียร์ นักบวชยกเหยือกของคุณขึ้นถวายเป็นเหยือกแรก','You mix red ochre into the beer, and the priests offer your jar first.')})]},
{id:'a6_famine',a:[20,60],w:4,ch:6,cond:S=>S.nile==='low'||era6(S.ya)==='fip',t:X('ยุ้งข้าวที่ว่างเปล่า','The empty granaries'),
 x:X('น้ำไนล์ขึ้นน้อย ยุ้งของหลายบ้านว่างแล้ว เพื่อนบ้านมาขอข้าวให้ลูก ส่วนเจ้าเมืองประกาศว่าจะแจกข้าวจากยุ้งของเขา','The Nile was low and many granaries are already empty. A neighbour comes begging grain for their children, and the local lord announces he will hand out grain from his stores.'),
 n:X('ผู้ปกครองท้องถิ่นชาวอียิปต์หลายคนจารึกไว้ในสุสานว่า “ข้าให้ขนมปังแก่คนหิว และให้เสื้อผ้าแก่คนเปลือย” การเลี้ยงดูผู้คนในยามอดอยากเป็นสิ่งที่พิสูจน์ว่าผู้ปกครองรักษามาอัต ความถูกต้องของโลก','Many Egyptian officials wrote in their tombs, “I gave bread to the hungry and clothes to the naked.” Feeding people in famine proved that a ruler upheld Ma’at, the right order of the world.'),
 o:[opt(X('แบ่งข้าวให้เพื่อนบ้าน','Share your grain with the neighbour'),S=>{fx({f:-6,b:6,p:2});return X('ลูกของเพื่อนบ้านรอดผ่านฤดูนั้นไปได้ เขาไม่เคยลืม','The neighbour’s children survive the season. They never forget.')}),
    opt(X('เฝ้ายุ้งของตัวเองไว้','Guard your own store'),S=>{fx({b:-4,f:2});return X('ครอบครัวของคุณอิ่ม แต่คุณได้ยินเสียงเด็กร้องจากบ้านข้างๆ ทุกคืน','Your family eats, but every night you hear children crying next door.')}),
    opt(X('ไปต่อแถวรับข้าวของเจ้าเมือง','Queue for the lord’s grain'),S=>{fx({f:5,b:-1});return X('แถวยาวตั้งแต่เช้ามืด แต่คุณได้ข้าวกลับบ้านหนึ่งตะกร้า','The queue starts before dawn, but you bring home a basket of grain.')})]},
{id:'a6_lettdead',a:[25,75],w:4,ch:6,cond:S=>S.ppl.some(p=>p.dead&&p.tr>=50),t:X('จดหมายถึงคนตาย','A letter to the dead'),
 xf:S=>{const p=S.ppl.find(p=>p.dead&&p.tr>=50);S.ldP=p;return PX(p,'หลังจาก{p}จากไป บ้านของคุณมีแต่เรื่องร้าย คนแก่ในหมู่บ้านแนะนำให้เขียนจดหมายถึงเขาลงบนชามดินเผา แล้ววางไว้ที่โบสถ์หน้าหลุมศพพร้อมอาหาร','Since {p} died, your house has had nothing but trouble. An old woman of the village says to write to them on a pottery bowl and leave it, with food, at the tomb chapel.')},
 n:X('ชาวอียิปต์เขียน “จดหมายถึงคนตาย” บนชามหรือกระดาษปาปิรุส ขอให้ญาติที่ตายแล้วช่วยปกป้อง หรือหยุดทำให้คนเป็นเดือดร้อน จดหมายฉบับหนึ่งจากราชอาณาจักรใหม่เป็นของชายที่เขียนถึงภรรยาที่ตายไปแล้ว ถามว่าเขาทำอะไรผิด ทั้งที่ดูแลเธอดีมาตลอด','Egyptians wrote “letters to the dead” on bowls or papyrus, asking dead relatives for protection, or to stop troubling the living. One New Kingdom letter is from a man to his dead wife, asking what he did wrong, when he always cared for her.'),
 o:[wOpt6(X('ขอให้เขาคุ้มครองลูกๆ','Ask them to protect the children'),S=>{doWrite6(S,'letter');S.ldead=1;fx({b:6});return PX(S.ldP,'คุณวางชามขนมปังและเบียร์ไว้หน้าหลุมของ{p} คืนนั้นคุณหลับสบายเป็นครั้งแรกในรอบหลายเดือน','You leave a bowl of bread and beer at {p}’s tomb. That night you sleep well for the first time in months.')}),
    wOpt6(X('ขอโทษสำหรับเรื่องที่ค้างคา','Ask forgiveness for what was left unsaid'),S=>{doWrite6(S,'letter');S.ldead=1;fx({b:8});return X('คุณเขียนสิ่งที่ไม่เคยพูดตอนเขายังอยู่ แล้วร้องไห้จนชามเปียก','You write what you never said while they lived, and weep until the bowl is wet.')}),
    opt(X('ไปเล่าข่าวในบ้านให้ฟังเฉยๆ','Simply go and tell them the family news'),S=>{fx({b:4,so:1});return X('คุณนั่งข้างหลุม เล่าเรื่องหลานที่เพิ่งหัดเดิน เหมือนเขายังนั่งฟังอยู่','You sit by the tomb telling them about the grandchild just learning to walk, as if they were still listening.')})]},
/* ----- elder ----- */
{id:'e6_shabti',deck:'elder',w:3,ch:6,a:[45,85],t:X('คนรับใช้ในโลกหน้า','Servants for the next world'),
 x:X('ช่างปั้นในหมู่บ้านขายตุ๊กตาชับติตัวเล็ก ว่ากันว่าในโลกหลังความตาย เมื่อถูกเรียกไปทำนาให้เทพ ชับติจะตอบว่า “ข้าอยู่นี่!” แล้วทำงานแทน','The village potter sells little shabti figures. They say that in the afterlife, when you are called to work the god’s fields, a shabti will answer “Here I am!” and work in your place.'),
 n:X('ชับติถูกฝังพร้อมผู้ตาย และมักมีคาถาบทที่ 6 ของคัมภีร์แห่งความตายเขียนไว้บนตัว ในราชอาณาจักรใหม่ตอนปลาย บางคนมีชุดชับติ 401 ตัว คือคนงาน 365 ตัวสำหรับทุกวันของปี กับหัวหน้าคนงานอีก 36 ตัว','Shabtis were buried with the dead, often inscribed with Spell 6 of the Book of the Dead. By the late New Kingdom some burials had sets of 401: 365 workers, one for each day of the year, and 36 overseers.'),
 o:[Object.assign(opt(X('ซื้อทั้งชุด','Buy a whole set'),S=>{S.ag-=3;S.shab=1;fx({b:4});return X('ชับติเรียงเป็นแถวเต็มกล่อง คุณหัวเราะว่าในที่สุดก็ไม่ต้องทำนาอีกแล้ว','The shabtis fill the box in rows. You laugh that at last you will never have to farm again.')}),{lockF:S=>S.ag<3,lockT:X('ต้องมีของมูลค่า 3 เดเบน','Needs 3 deben in goods')}),
    opt(X('ซื้อตัวเดียวก็พอ','Just one will do'),S=>{S.shab=1;fx({b:2});return X('คุณเลือกตัวที่หน้าตาขยันที่สุด','You choose the one with the most hard-working face.')}),
    opt(X('ปั้นเองให้หลานช่วยทาสี','Make your own, and let the grandchildren paint it'),S=>{S.shab=1;fx({b:5,cr:2});return X('ชับติของคุณหน้าเบี้ยว แต่หลานวาดรอยยิ้มให้มันด้วย','Your shabti’s face is crooked, but the grandchildren paint it a smile.')})]},
{id:'e6_teach',deck:'elder',w:3,ch:6,a:[50,85],t:X('คำสอนถึงลูกหลาน','Teachings for the children'),
 x:X('ลูกๆ มานั่งรอบตัวคุณ อยากฟังว่าชีวิตสอนอะไรคุณบ้าง','Your children gather round, wanting to hear what life has taught you.'),
 n:X('“คำสอนของพทาห์โฮเทป” เชื่อกันว่าเป็นของขุนนางผู้ใหญ่ในราชอาณาจักรเก่า และรอดมาในฉบับคัดลอกจากราชอาณาจักรกลาง เป็นหนังสือคำสอนที่เก่าแก่ที่สุดเล่มหนึ่งของโลก มีประโยคว่า “อย่าหยิ่งในความรู้ของตน จงปรึกษาทั้งคนโง่และคนฉลาด”','The Teaching of Ptahhotep, attributed to an Old Kingdom vizier and preserved in Middle Kingdom copies, is one of the world’s oldest books of advice. It says: “Do not be proud of your knowledge; consult the ignorant as well as the wise.”'),
 o:[wOpt6(X('เขียนคำสอนเก็บไว้','Write your teaching down'),S=>{doWrite6(S,'copy');fx({kn:3,b:4});return X('คุณเขียนว่า “จงฟังคนที่ไม่รู้หนังสือด้วย เพราะเขารู้ในสิ่งที่หนังสือไม่รู้”','You write: “Listen to those who cannot read as well, for they know what books do not.”')}),
    opt(X('เล่าให้ฟังข้างเตา','Tell them by the oven'),S=>{fx({b:5,so:2});return X('หลานคนเล็กหลับไปบนตักคุณก่อนเรื่องจะจบ','The youngest grandchild falls asleep in your lap before you finish.')}),
    opt(X('บอกให้ทุกคนเป็นอาลักษณ์','Tell them all to become scribes'),S=>{fx({b:1,kn:1});return X('ทุกคนหัวเราะ เพราะคุณพูดเหมือนครูในโรงเรียนอาลักษณ์ไม่มีผิด','Everyone laughs: you sound exactly like a schoolteacher.')})]},
{id:'e6_valley',deck:'elder',w:4,ch:6,a:[40,85],cond:S=>era6(S.ya)==='nk'&&['the','dem'].includes(S.rg),t:X('เทศกาลอันงดงามแห่งหุบเขา','The Beautiful Festival of the Valley'),
 x:X('เรือของเทพอามุนข้ามแม่น้ำมาที่ฝั่งตะวันตก ทุกครอบครัวขนอาหารและดอกไม้ไปที่สุสานของบรรพบุรุษ กิน ดื่ม และนอนค้างคืนอยู่กับคนตาย','Amun’s boat crosses to the west bank. Every family carries food and flowers to their ancestors’ tombs, to eat, drink and spend the night with the dead.'),
 n:X('เทศกาลอันงดงามแห่งหุบเขาจัดทุกปีที่ธีบส์ ในราชอาณาจักรใหม่ เป็นวันที่คนเป็นกับคนตายได้ “กินข้าวด้วยกัน” ภาพในสุสานแสดงงานเลี้ยงที่มีนักดนตรี ดอกบัว และเหล้าองุ่น','The Beautiful Festival of the Valley was held every year at Thebes in the New Kingdom, a day when the living and the dead “dined together”. Tomb paintings show banquets with musicians, lotus flowers and wine.'),
 o:[opt(X('เล่าเรื่องบรรพบุรุษให้หลานฟัง','Tell the grandchildren about the ancestors'),S=>{fx({b:6,so:2});return X('คุณเล่าจนดึก ชื่อของปู่ย่าตายายถูกเอ่ยซ้ำแล้วซ้ำอีกใต้แสงตะเกียง','You talk late into the night, and the old names are spoken again and again under the lamp.')}),
    opt(X('นั่งเงียบๆ ข้างหลุมของคนที่รัก','Sit quietly by a loved one’s tomb'),S=>{fx({b:5});return X('ลมจากทะเลทรายเย็นลง คุณรู้สึกเหมือนมีคนนั่งอยู่ข้างๆ','The desert wind cools, and you feel someone sitting beside you.')})]},
];

/* ---------- chapter 06 career decisions ---------- */
const DEC_CAR6=[
{id:'k6_count',a:[16,60],w:4,ch:6,cond:S=>S.car==='scribe',t:X('นับวัวเพื่อเก็บภาษี','The cattle count'),
 x:X('คุณตามขุนนางไปนับวัวและเก็บภาษีในหมู่บ้าน ผู้ใหญ่บ้านคนหนึ่งส่งไม่ครบ คนคุมถือไม้เรียวรออยู่ข้างหลังเขา','You go with an official to count cattle and collect taxes in the villages. One village head is short, and the overseers stand behind him with sticks.'),
 n:X('ภาพในสุสานขุนนางยุคราชอาณาจักรเก่า แสดงอาลักษณ์นั่งจดตัวเลขขณะที่ผู้ใหญ่บ้านที่ส่งภาษีไม่ครบถูกลากตัวมาและถูกตี การนับวัวทั่วประเทศเป็นงานใหญ่จนใช้ตั้งชื่อปี เช่น “ปีแห่งการนับวัวครั้งที่สิบ”','Old Kingdom tomb scenes show scribes writing numbers while village heads who fell short on taxes are dragged forward and beaten. The national cattle count was so important that years were named after it, as in “the year of the tenth count”.'),
 o:[opt(X('จดตามจริงทุกตัว','Record every animal truly'),S=>{S.papN++;fx({p:4,b:-2});return X('ตัวเลขของคุณถูกต้องทุกตัว ขุนนางพอใจ แต่คุณไม่กล้ามองหน้าผู้ใหญ่บ้านคนนั้น','Your figures are exact. The official is pleased, but you cannot meet the village head’s eyes.')}),
    opt(X('นับวัวผอมๆ ข้ามไปสองตัว','Skip two scrawny cows in the count'),S=>{S.papN++;if(rnd()<.3){fx({p:-6});return X('ขุนนางนับซ้ำเอง แล้วจ้องคุณนาน','The official recounts them himself, and stares at you for a long time.')}fx({b:5});return X('ผู้ใหญ่บ้านรอดจากไม้เรียว เขาส่งปลาแห้งมาให้คุณทุกปีจากนั้น','The village head is spared the stick. He sends you dried fish every year after.')})]},
{id:'k6_merer',a:[16,60],w:6,ch:6,cond:S=>(S.car==='scribe'||S.car==='builder')&&S.ya<=4614&&S.ya>=4560,t:X('บันทึกประจำวันของทีมขนหิน','The stone crew’s logbook'),
 x:X('หัวหน้าทีมให้คุณจดบันทึกทุกวัน ว่าเรือของทีมขนหินปูนจากเหมืองตูรามาส่งที่กีซากี่เที่ยว พักที่ไหน และกินอะไร','The team leader has you keep a daily log: how many boatloads of limestone the crew carries from the Tura quarries to Giza, where they stop, and what they eat.'),
 n:X('ในปี 2013 นักโบราณคดีพบกระดาษปาปิรุสที่ท่าเรือวาดี อัล-จาร์ฟ ริมทะเลแดง เป็นบันทึกของหัวหน้าทีมชื่อเมเรอร์ สมัยพระเจ้าคูฟู เล่าการขนหินปูนทางเรือมาสร้างมหาพีระมิด เป็นกระดาษปาปิรุสที่มีตัวหนังสือที่เก่าที่สุดเท่าที่รู้จัก','In 2013 archaeologists found papyri at the harbour of Wadi al-Jarf on the Red Sea: the logbook of a team leader named Merer, under King Khufu, describing how his crew shipped limestone for the Great Pyramid. They are the oldest inscribed papyri known.'),
 o:[opt(X('จดทุกอย่างละเอียด','Note everything in detail'),S=>{S.papN+=3;S.papK.account=(S.papK.account||0)+3;fx({kn:4,p:3});return X('บันทึกของคุณยาวหลายม้วน หัวหน้าเก็บไว้ในกล่องไม้','Your log fills several rolls. The leader keeps it in a wooden box.')}),
    opt(X('เขียนชื่อตัวเองไว้ท้ายม้วน','Write your own name at the end of the roll'),S=>{S.papN++;S.nameTab=1;fx({p:2});ms(X('เขียนชื่อตัวเองไว้ในบันทึกการสร้างพีระมิด','Wrote your own name into the pyramid builders’ log'));return X('ชื่อของคุณอาจอยู่ในกล่องนั้นนานกว่าตัวพีระมิดเสียอีก','Your name may outlast even the pyramid’s smooth casing.')})]},
{id:'k6_boundary',a:[16,65],w:4,ch:6,cond:S=>S.car==='farmer',t:X('หลักเขตที่หายไป','The vanished boundary stone'),
 x:X('น้ำลดแล้ว โคลนทับหลักเขตที่นาจนหายไป คุณเห็นเพื่อนบ้านแอบปักหลักใหม่ล้ำเข้ามาในนาของคุณสองก้าว','The flood has gone down and mud has buried the field markers. You see your neighbour quietly setting a new stone two paces into your land.'),
 n:X('หลังน้ำท่วมทุกปี “คนขึงเชือก” ของรัฐมาวัดที่นาใหม่ คำสอนของอาเมนเอโมเปเตือนว่า “อย่าย้ายหลักเขตของที่นา” และในคาถาบทที่ 125 ผู้ตายต้องกล่าวต่อหน้าเทพว่า “ข้าไม่ได้ย้ายหลักเขต”','After each flood, state “rope-stretchers” re-measured the fields. The Teaching of Amenemope warns, “Do not move the markers on the borders of fields”, and in Spell 125 the dead must declare before the gods, “I have not moved the boundary stone.”'),
 o:[opt(X('เรียกคนขึงเชือกมาวัดใหม่','Call the rope-stretchers to measure again'),S=>{fx({p:3,kn:2});return X('เชือกที่ขึงตรงพิสูจน์ว่าคุณพูดถูก หลักถูกย้ายกลับ','The taut rope proves you right, and the stone goes back.')}),
    opt(X('ย้ายหลักกลับเองตอนกลางคืน','Move it back yourself at night'),S=>{fx({b:-2,sv:2});return X('เช้าวันต่อมา เพื่อนบ้านมองหลักแล้วมองคุณ แต่ไม่พูดอะไร','Next morning your neighbour looks at the stone, then at you, and says nothing.')}),
    opt(X('ย้ายหลักของคุณล้ำเข้าไปบ้าง','Push your own marker into their field'),S=>{fx({f:3,b:-4});S.boundary=1;return X('นาของคุณกว้างขึ้นนิดหนึ่ง แต่ทุกครั้งที่ได้ยินคาถาบทที่ 125 คุณรู้สึกหนาว','Your field grows a little, but whenever you hear Spell 125 you feel cold.')})]},
{id:'k6_skiff',a:[14,60],w:4,ch:6,cond:S=>S.car==='fisher',t:X('ฮิปโปใต้เรือกก','A hippo under the skiff'),
 x:X('ขณะคุณกางตาข่ายในบึง น้ำใต้เรือกกปาปิรุสพองขึ้น ฮิปโปตัวหนึ่งกำลังจะโผล่ขึ้นมาตรงใต้เรือพอดี','As you spread your nets in the marsh, the water bulges under your papyrus skiff. A hippo is about to surface right beneath you.'),
 n:X('เรือของคนหาปลาอียิปต์ทำจากกกปาปิรุสมัดเป็นฟ่อน เบาและพลิกคว่ำง่าย ภาพในสุสานแสดงคนหาปลาใช้ตาข่ายลากและไม้ขว้างล่านก ขณะที่ฮิปโปและจระเข้ซุ่มอยู่ใต้น้ำ','Egyptian fishermen used skiffs of bundled papyrus, light and easy to overturn. Tomb scenes show them with drag nets and throwing sticks for birds, while hippos and crocodiles lurk under the water.'),
 o:[opt(X('กระโดดลงน้ำว่ายเข้าฝั่ง','Jump and swim for the bank'),S=>{if(rnd()<.25){fx({h:-14});S.inj=1;return X('คุณว่ายเข้ากอกก แต่จระเข้ตัวหนึ่งงับขาคุณก่อนที่เพื่อนจะลากคุณขึ้นมาได้','You make for the reeds, but a crocodile snaps at your leg before your friend hauls you out.')}fx({b:-2});return X('คุณขึ้นฝั่งได้ หอบจนพูดไม่ออก เรือของคุณลอยคว่ำอยู่กลางบึง','You reach the bank, too breathless to speak. Your skiff floats upside down in the marsh.')}),
    opt(X('นอนราบนิ่งๆ ในเรือ','Lie flat and still in the boat'),S=>{if(rnd()<.7){fx({sv:4,b:3});return X('ฮิปโปโผล่ขึ้นข้างเรือ พ่นน้ำ แล้วจมลงไปอีกทาง','The hippo surfaces beside the boat, snorts, and sinks away elsewhere.')}fx({h:-8});return X('เรือพลิกคว่ำ คุณโผล่ขึ้นมาท่ามกลางตาข่ายที่พันตัว','The boat flips. You come up tangled in your own nets.')}),
    opt(X('ตีน้ำด้วยไม้พายให้ดังที่สุด','Slap the water with your pole as loud as you can'),S=>{fx({so:2,sv:2});return X('เสียงดังทำให้ฮิปโปหันไปอีกทาง นกทั้งบึงบินขึ้นพร้อมกัน','The noise turns the hippo away, and every bird in the marsh rises at once.')})]},
{id:'k6_beer',a:[14,60],w:3,ch:6,cond:S=>S.car==='brewer',t:X('เบียร์จากมอลต์','Beer from malt'),
 x:X('หัวหน้าโรงเบียร์ทำแบบเดิม คืออบขนมปังเบียร์แล้วบี้ลงน้ำ แต่ช่างหนุ่มคนหนึ่งบอกว่าถ้าเพาะข้าวให้งอกแล้วต้มบางส่วน เบียร์จะหวานกว่า','The head brewer does it the old way, baking beer bread and crumbling it into water. A young brewer says that if you sprout the grain and cook part of it, the beer comes out sweeter.'),
 n:X('การส่องกล้องจุลทรรศน์ดูคราบในโถเบียร์จากเดร์เอล-เมดินาและอามาร์นา โดยนักโบราณคดีเดลเวน ซามูเอล ในทศวรรษ 1990 พบว่าคนทำเบียร์ผสมข้าวมอลต์ที่ต้มกับที่ไม่ได้ต้ม เบียร์อียิปต์ข้นและมีรสหวาน ปันส่วนรายวันของคนงานมักรวมขนมปังและเบียร์หลายเหยือก','Microscope studies of residues in beer jars from Deir el-Medina and Amarna, by the archaeologist Delwen Samuel in the 1990s, showed that brewers mixed cooked and uncooked malted grain. Egyptian beer was thick and sweetish, and workers’ daily rations often included bread and several jugs of beer.'),
 o:[opt(X('ลองวิธีใหม่','Try the new way'),S=>{if(rnd()<.6){fx({cr:5,p:3});S.cxp+=2;return X('เบียร์หวานจนคนงานต่อแถวมาขอ หัวหน้าบ่นแต่แอบขอสูตร','The beer is so sweet the workers queue for it. The head brewer grumbles, then quietly asks for the method.')}fx({cr:2});return X('ครั้งแรกเบียร์เปรี้ยว แต่คุณจดจำไว้ว่าต้องต้มนานแค่ไหน','The first batch turns sour, but you learn how long to cook it.')}),
    opt(X('ทำแบบเดิม','Keep to the old way'),S=>{fx({kn:2});return X('เบียร์ของคุณเหมือนเบียร์ของปู่ และนั่นก็ไม่ใช่เรื่องเสียหาย','Your beer tastes like your grandfather’s, and that is no bad thing.')})]},
{id:'k6_khnum',a:[14,60],w:3,ch:6,cond:S=>S.car==='potter',t:X('แป้นหมุนของเทพคนุม','Khnum’s wheel'),
 x:X('ครูช่างปั้นบอกว่าเทพคนุมปั้นเด็กทุกคนบนแป้นหมุนก่อนจะใส่ลงในท้องแม่ ช่างปั้นจึงต้องปั้นหม้อทุกใบอย่างตั้งใจเหมือนเทพ','Your master says the god Khnum shapes every child on his potter’s wheel before placing it in its mother’s womb, so a potter must make every pot as carefully as the god.'),
 n:X('ชาวอียิปต์เชื่อว่าเทพคนุมหัวแกะปั้นร่างกายและวิญญาณ “กา” ของคนบนแป้นหมุน ภาพสลักในวิหารแสดงพระองค์ปั้นกษัตริย์ทารก แป้นหมุนปั้นหม้อใช้ในอียิปต์มาตั้งแต่ราชอาณาจักรเก่า','Egyptians believed the ram-headed Khnum shaped people’s bodies and their ka on a potter’s wheel; temple reliefs show him modelling the infant king. The potter’s wheel was used in Egypt from the Old Kingdom.'),
 o:[opt(X('ปั้นช้าๆ ทีละใบ','Throw slowly, one pot at a time'),S=>{fx({cr:5});S.cxp+=2;return X('หม้อของคุณบางและเบาจนนักบวชสั่งไปใช้ในวิหาร','Your pots grow so thin and light that the priests order them for the temple.')}),
    opt(X('ปั้นให้เร็วและได้มาก','Throw fast, and make many'),S=>{addItem('pot');fx({f:3});return X('คุณได้หม้อเต็มลาน และแลกข้าวได้มากกว่าทุกปี','The yard fills with pots, and you trade for more grain than ever.')})]},
{id:'k6_sledge',a:[14,50],w:5,ch:6,cond:S=>S.car==='builder'&&['ok','mk'].includes(era6(S.ya)),t:X('ลากหินบนเลื่อน','Hauling the sledge'),
 x:X('ทีมของคุณต้องลากหินก้อนใหญ่บนเลื่อนไม้ข้ามทราย เชือกตึงจนแทบขาด คนแก่ในทีมบอกให้คุณเอาน้ำไปราดทรายข้างหน้าเลื่อน','Your gang must drag a huge block on a wooden sledge across the sand. The ropes strain to breaking. An old hand tells you to pour water on the sand in front of the sledge.'),
 n:X('ภาพในสุสานของเจฮูตีโฮเทปจากราชอาณาจักรกลาง แสดงคนหนึ่งยืนราดน้ำหน้าเลื่อนที่ลากรูปปั้นยักษ์ การทดลองในปี 2014 พบว่าทรายที่เปียกพอดีช่วยลดแรงที่ต้องใช้ลากลงได้ราวครึ่งหนึ่ง','A Middle Kingdom painting in the tomb of Djehutihotep shows a man pouring water in front of a sledge carrying a colossal statue. A 2014 experiment found that sand wetted just right roughly halves the force needed to pull.'),
 o:[opt(X('ราดน้ำตามที่คนแก่บอก','Pour the water as the old hand says'),S=>{fx({kn:4,p:2});S.cxp+=2;return X('เลื่อนไถลไปข้างหน้าเหมือนมีคนช่วยผลัก ทั้งทีมโห่ร้อง','The sledge slides forward as if someone were pushing, and the gang cheers.')}),
    opt(X('ดึงให้แรงขึ้น','Just pull harder'),S=>{fx({h:-4,sv:3});return X('หินขยับทีละนิด มือของทุกคนเลือดออกก่อนตะวันตก','The block creeps along; everyone’s hands are bleeding before sunset.')}),
    opt(X('ร้องเพลงจังหวะให้ทีม','Sing a rhythm for the gang'),S=>{fx({so:4,b:3});return X('ทุกคนดึงพร้อมกันตามเพลงของคุณ ทีมอื่นเริ่มร้องตาม','Everyone pulls together to your song, and the other gangs start singing it too.')})]},
{id:'k6_tomb',a:[16,60],w:5,ch:6,cond:S=>S.car==='builder'&&S.rg==='dem',t:X('วันหยุดเพื่อหมักเบียร์','A day off to brew beer'),
 x:X('พรุ่งนี้เป็นงานเลี้ยงในบ้าน คุณอยากหยุดงานในสุสานหลวงหนึ่งวันเพื่อหมักเบียร์ อาลักษณ์ของทีมจดทุกคนที่ขาดงานพร้อมเหตุผล','Tomorrow is a family feast and you want a day off from the royal tomb to brew beer. The gang’s scribe notes everyone who is absent, and why.'),
 n:X('เศษหินจากเดร์เอล-เมดินาบันทึกเหตุผลที่คนงานขาดงาน เช่น หมักเบียร์ ถูกแมงป่องต่อย ทำศพให้ญาติ ภรรยาหรือลูกสาวมีประจำเดือน และแม้แต่ “ไปถวายของให้เทพของเขา” คนงานในสุสานได้ไส้ตะเกียงเป็นจำนวนนับ ซึ่งใช้วัดเวลาทำงานในความมืดด้วย','Ostraca from Deir el-Medina record why workmen were absent: brewing beer, being stung by a scorpion, embalming a relative, a wife or daughter menstruating, even “offering to his god”. Workers were issued counted lamp wicks, which also measured their hours in the dark.'),
 o:[opt(X('ขอหยุด แล้วหมักเบียร์','Take the day and brew'),S=>{fx({b:5});S.papK.absent=1;return X('ข้างชื่อของคุณ อาลักษณ์เขียนว่า “ขาด: หมักเบียร์” อีกสามพันปีต่อมา อาจมีคนอ่านแล้วหัวเราะ','Beside your name the scribe writes, “absent: brewing beer”. Three thousand years later someone may read it and laugh.')}),
    opt(X('ทำงานต่อใต้แสงตะเกียง','Keep working by lamplight'),S=>{fx({cr:3,p:2});S.cxp+=2;return X('คุณวาดเทพอนูบิสบนผนังสุสานจนเสร็จ หัวหน้าช่างพยักหน้าให้','You finish painting Anubis on the tomb wall, and the master craftsman nods.')})]},
{id:'k6_embalm',a:[16,60],w:4,ch:6,cond:S=>S.car==='embalmer',t:X('เจ็ดสิบวัน','Seventy days'),
 x:X('ครอบครัวยากจนนำร่างของแม่มาให้ทำมัมมี่ แต่จ่ายได้แค่แบบถูกที่สุด หัวหน้าบอกให้ทำตามราคาที่จ่าย','A poor family brings their mother’s body to be embalmed, but can only pay for the cheapest treatment. Your master says to do only what they paid for.'),
 n:X('เฮโรโดตัส นักเขียนกรีก เล่าว่าการทำมัมมี่มีสามระดับราคา แบบดีที่สุดเอาสมองออกทางจมูกด้วยตะขอเหล็ก ควักอวัยวะภายในออก แล้วหมักร่างในเกลือนาตรอนจนแห้ง ทั้งกระบวนการใช้เจ็ดสิบวัน หัวใจถูกทิ้งไว้ในร่าง เพราะจะถูกชั่งในโลกหลังความตาย','The Greek writer Herodotus describes three price grades of embalming. The best removed the brain through the nose with an iron hook, took out the organs and dried the body in natron salt; the whole process took seventy days. The heart was left in the body, to be weighed in the afterlife.'),
 o:[opt(X('ทำให้ดีที่สุดอยู่ดี','Do your best work anyway'),S=>{fx({b:6,p:-1,f:-2});return X('คุณใช้นาตรอนและผ้าลินินของตัวเอง ลูกสาวของผู้ตายจูบมือคุณตอนมารับร่าง','You use your own natron and linen. The dead woman’s daughter kisses your hand when she comes for the body.')}),
    opt(X('ทำตามราคาที่จ่าย','Do only what they paid for'),S=>{fx({p:2});return X('งานเสร็จเร็ว หัวหน้าพอใจ ครอบครัวนั้นไม่รู้ว่ามีวิธีที่ดีกว่า','The work is quick, your master is pleased, and the family never knows there was better.')}),
    opt(X('ใส่เครื่องรางให้โดยไม่คิดเงิน','Slip in an amulet at no charge'),S=>{fx({b:4,so:2});return X('คุณวางเครื่องรางรูปแมลงสคารับไว้บนหัวใจของเธอ ให้หัวใจไม่พูดสิ่งที่ไม่ดีตอนถูกชั่ง','You lay a scarab amulet over her heart, so the heart will say nothing against her at the weighing.')})]},
{id:'k6_oracle',a:[18,65],w:4,ch:6,cond:S=>S.car==='priest'&&['mk','nk'].includes(era6(S.ya)),t:X('แบกเรือของเทพ','Carrying the god’s boat'),
 x:X('คุณเป็นหนึ่งในนักบวชที่แบกเรือศักดิ์สิทธิ์ของเทพในขบวนแห่ ชาวนายากจนคนหนึ่งถามเทพว่าที่นาผืนหนึ่งเป็นของเขาหรือของเศรษฐี เศรษฐีส่งสายตามาหาคุณ','You are one of the priests carrying the god’s sacred boat in procession. A poor farmer asks the god whether a field is his or a rich man’s, and the rich man catches your eye.'),
 n:X('ในการถามเทพ คำตอบมาจากการเคลื่อนไหวของเรือที่นักบวชหลายคนแบกอยู่ จึงอาจถูกชักจูงได้ บันทึกบางฉบับแสดงว่าผู้แพ้ยื่นถามใหม่กับเทพองค์อื่น','In an oracle, the answer came from how the boat, carried by many priests, moved, so it could be swayed. Some records show losers taking their question to another god.'),
 o:[opt(X('ปล่อยให้เทพตัดสินเอง','Let the god decide'),S=>{fx({b:4,p:1});return X('เรือโน้มไปทางชาวนา เขาร้องไห้ คุณไม่รู้ว่าแขนใครเป็นคนพาไป','The boat leans towards the farmer, who weeps. You will never know whose arms moved it.')}),
    opt(X('เอียงไหล่ไปทางเศรษฐี','Lean your shoulder toward the rich man'),S=>{S.ag+=3;fx({b:-6,p:2});return X('เรือโน้มไปทางเศรษฐี วันรุ่งขึ้นมีกระสอบข้าวมาวางหน้าบ้านคุณ คุณนอนไม่หลับหลายคืน','The boat leans to the rich man. Next day a sack of grain appears at your door, and you lie awake for nights.')})]},
{id:'k6_case',a:[18,65],w:4,ch:6,cond:S=>S.car==='physician',t:X('กะโหลกที่แตก','The broken skull'),
 x:X('มีคนแบกคนงานที่หินตกใส่หัวมาหาคุณ กะโหลกแตก และเขาพูดไม่ได้ ตำราของคุณบอกว่า “เป็นโรคที่ไม่ควรรักษา”','Workmen carry in a man hit on the head by a falling stone. His skull is broken and he cannot speak. Your book says: “an ailment not to be treated.”'),
 n:X('ปาปิรุสเอ็ดวิน สมิธ จัดการบาดเจ็บเป็นสามกลุ่ม “โรคที่ข้าจะรักษา” “โรคที่ข้าจะต่อสู้ด้วย” และ “โรคที่ไม่ควรรักษา” ตำรานี้ยังมีคำอธิบายเรื่องสมองที่เก่าแก่ที่สุดที่รู้จัก และสังเกตว่าบาดเจ็บที่ศีรษะทำให้แขนขาอ่อนแรงหรือเป็นอัมพาตได้','The Edwin Smith Papyrus sorts injuries into “an ailment I will treat”, “an ailment I will contend with” and “an ailment not to be treated”. It contains the oldest known description of the brain, and notes that a head injury can weaken or paralyse the limbs.'),
 o:[opt(X('รักษาเท่าที่ทำได้','Treat him as best you can'),S=>{if(rnd()<.35){fx({p:6,kn:4});return X('เขาตื่นขึ้นในวันที่สาม และค่อยๆ พูดชื่อลูกได้ คุณจดกรณีนี้ไว้ให้ศิษย์อ่าน','He wakes on the third day and slowly says his children’s names. You write the case down for your pupils.')}fx({b:-4,kn:3});return X('เขาตายในคืนนั้น ครอบครัวไม่โทษคุณ แต่คุณโทษตัวเอง','He dies that night. His family does not blame you, but you blame yourself.')}),
    opt(X('ทำตามตำรา ให้เขาพักอย่างสงบ','Follow the book and let him rest in peace'),S=>{fx({kn:2,b:1});return X('คุณนั่งอยู่ข้างเขา ท่องคาถาให้หลับสบาย จนเขาจากไปอย่างสงบ','You sit beside him chanting a spell for easy sleep until he slips away.')})]},
{id:'k6_peseshet',a:[16,40],w:4,ch:6,cond:S=>S.car==='physician'&&S.sex==='f',t:X('หัวหน้าหมอหญิง','The overseer of women physicians'),
 x:X('คุณได้ยินว่าในวังมีผู้หญิงที่มีตำแหน่ง “หัวหน้าหมอหญิง” คนในหมู่บ้านบอกว่าผู้หญิงควรเป็นหมอตำแยเท่านั้น','You hear that at the palace there is a woman with the title “overseer of women physicians”. People in the village say women should only be midwives.'),
 n:X('จารึกในสุสานยุคราชอาณาจักรเก่าของหญิงชื่อเพเซเชต ราว 2500 ปีก่อนคริสตกาล ระบุตำแหน่ง “หัวหน้าหมอหญิง” เธอเป็นหนึ่งในผู้หญิงในวงการแพทย์ที่เก่าแก่ที่สุดที่มีชื่อปรากฏ','An Old Kingdom tomb inscription of a woman named Peseshet, about 2500 BCE, gives her the title “overseer of women physicians”. She is one of the earliest women in medicine known by name.'),
 o:[opt(X('เดินทางไปขอเรียนกับเธอ','Travel to learn from her'),S=>{fx({kn:6,p:3,f:-3});S.cxp+=3;return X('เธอให้คุณดูแลคนไข้หญิงในวัง และสอนตำรายาที่ผู้ชายไม่เคยอ่าน','She sets you to tend the palace women, and teaches you remedies no man has read.')}),
    opt(X('รักษาคนในหมู่บ้านต่อไป','Keep treating your village'),S=>{fx({b:3,so:2});return X('ไม่นาน คนที่เคยพูดว่าผู้หญิงเป็นหมอไม่ได้ ก็พาลูกที่ป่วยมาหาคุณ','Soon the people who said women cannot be physicians bring you their sick children.')})]},
{id:'k6_fort',a:[16,45],w:4,ch:6,cond:S=>S.car==='soldier'&&era6(S.ya)==='mk',t:X('ป้อมที่แก่งน้ำตก','The fortress at the cataract'),
 x:X('กองของคุณถูกส่งไปประจำป้อมอิฐดิบที่แก่งน้ำตกแห่งที่สองในนูเบีย คอยตรวจเรือและคาราวานที่ผ่านแม่น้ำ','Your company is posted to a mud-brick fortress at the Second Cataract in Nubia, checking every boat and caravan on the river.'),
 n:X('กษัตริย์ราชอาณาจักรกลางสร้างป้อมใหญ่หลายแห่งริมแก่งน้ำตกแห่งที่สอง เช่นป้อมบูเฮน มีกำแพงหนาและคูน้ำ รายงานทางทหารจากที่นี่บันทึกแม้แต่การผ่านของชาวนูเบียกลุ่มเล็กๆ ป้อมเหล่านี้จมอยู่ใต้ทะเลสาบนัสเซอร์หลังสร้างเขื่อนอัสวาน','Middle Kingdom kings built great fortresses along the Second Cataract, such as Buhen, with thick walls and ditches. Military dispatches from them record even small groups of Nubians passing. The forts now lie under Lake Nasser, drowned by the Aswan High Dam.'),
 o:[opt(X('ตรวจเข้มทุกลำ','Search every boat thoroughly'),S=>{fx({p:4});return X('คุณจับคนลักลอบขนงาช้างได้ หัวหน้าส่งรายงานไปถึงพระราชา','You catch a man smuggling ivory, and your commander sends a report to the king.')}),
    opt(X('ผูกมิตรกับพ่อค้านูเบีย','Make friends with the Nubian traders'),S=>{fx({so:4,b:3});addItem('linen');return X('พ่อค้าคนหนึ่งสอนคำภาษาของเขาให้คุณ และให้ขนนกกระจอกเทศเป็นของขวัญ','One trader teaches you words of his language and gives you an ostrich feather.')})]},
{id:'k6_kadesh',a:[16,45],w:5,ch:6,cond:S=>S.car==='soldier'&&era6(S.ya)==='nk',t:X('รถศึกของศัตรู','The enemy chariots'),
 x:X('กองทัพเดินทัพไกลไปทางเหนือ จู่ๆ รถศึกของศัตรูหลายร้อยคันก็พุ่งออกมาจากหลังเนิน ตัดกองทัพออกเป็นสองท่อน','The army marches far to the north. Suddenly hundreds of enemy chariots burst from behind a hill and cut the column in two.'),
 n:X('รถศึกม้าลากถูกนำเข้ามาในอียิปต์ช่วงก่อนราชอาณาจักรใหม่ และกลายเป็นกำลังหลักของกองทัพจักรวรรดิ ในศึกคาเดช ปี 1274 ปีก่อนคริสตกาล รถศึกฮิตไทต์ซุ่มโจมตีกองทัพของรามเสสที่ 2 จนเกือบแตกพ่าย','Horse-drawn chariots came into Egypt shortly before the New Kingdom and became the core of the imperial army. At Kadesh in 1274 BCE, Hittite chariots ambushed Ramesses II’s army and nearly routed it.'),
 o:[opt(X('ตั้งแนวโล่ไว้','Hold the shield line'),S=>{if(rnd()<.7){fx({p:6,b:2});return X('แนวของคุณไม่แตก รถศึกหักเลี้ยวไปทางอื่น','Your line holds, and the chariots wheel away.')}fx({h:-14});S.inj=1;return X('ม้าศึกพุ่งชนแนว คุณถูกเหยียบจนซี่โครงหัก','The horses crash into the line, and you are trampled, ribs broken.')}),
    opt(X('หนีไปที่ค่าย','Run for the camp'),S=>{fx({p:-4,b:-2});return X('คุณรอด แต่ตอนเดินทัพกลับ ไม่มีใครเล่าเรื่องนี้ถึงตัวคุณ','You survive, but on the march home no one tells the story with you in it.')})]},
];
